// @couli/db: Kysely + pg access to the `app` schema (ADR-0001 §2).
// Table types come from `db.gen.ts`, generated by `pnpm db:snapshot`; never edit that file.
import { Kysely, PostgresDialect, type PostgresPool } from 'kysely';
import pg from 'pg';

import type { DB } from './db.gen.ts';
import { parseInt8, parseInt8Array } from './int8.ts';

export type { DB } from './db.gen.ts';
export {
  MONTH_PARTITIONED_TABLES,
  MONTHS_AHEAD,
  monthPartitionName,
  monthStartDate,
  monthsToEnsure,
  utcMonthStart,
} from './partitions.ts';
export type { MonthPartitionedTable } from './partitions.ts';
export { parsePgUrl, pgUrl, redactPgUrl } from './pg-url.ts';
export type { PgUrlOverrides, PgUrlParts } from './pg-url.ts';

/** Schema that holds every business table. */
export const APP_SCHEMA = 'app';

export type CreateDbOptions = {
  /** Pool size; per-process values are listed in ADR-0001 §4.2 #11. */
  max?: number;
  applicationName?: string;
} & (
  | { connectionString: string; poolFactory?: (config: pg.PoolConfig) => PostgresPool }
  // Platform infrastructure supplies its own discrete connection fields and lifecycle.
  | { connectionString?: never; poolFactory: (config: pg.PoolConfig) => PostgresPool }
);

const INT8_ARRAY_OID = 1016;

// int8 and int8[] are parsed as BigInt (ADR-0001 §4.2 #3). The override is scoped to pools
// created here, so libraries that own their connections (pg-boss, node-pg-migrate) keep pg's
// defaults.
function int8AsBigInt(): pg.TypeOverrides {
  const overrides = new pg.TypeOverrides();
  overrides.setTypeParser(pg.types.builtins.INT8, parseInt8);
  overrides.setTypeParser(INT8_ARRAY_OID, parseInt8Array);
  return overrides;
}

// pg-pool keeps a released client unless it is `!_queryable` or `_ending`, so a dead backend
// must leave the default client unqueryable before it goes back. It reaches the client in one
// of two ways:
// - As an 'error' event: the socket failed or closed, or a FATAL arrived with no query running.
//   pg marks the client unqueryable before emitting. pg-pool only listens to idle clients, so a
//   checked-out client needs its own listener, or Node turns the event into an uncaught
//   exception; the pool listener covers idle clients, which pg-pool already drops.
// - As the error of the query that was running when the server sent FATAL (for example
//   pg_terminate_backend while a statement is in flight). pg rejects that query but leaves the
//   client queryable until the socket closes later, so a caller that catches the error and
//   releases normally would hand the dead connection to the next borrower. Such errors are
//   recognised from the ErrorResponse itself (isConnectionLevel) and mark the client before the
//   query rejects.
// Ordinary statement errors (unique violation, division by zero, serialization failure) leave
// the session usable: the client stays queryable for the rest of the lease and is reused after
// release. Nothing here releases, destroys or rebuilds anything, which would double-handle
// pg-pool's own cleanup; the failing query, or the next one on that lease, still rejects
// through its own promise. This package has no logger, so nothing is reported here.
const CONNECTION_LEVEL_SQLSTATES = new Set(['57P01', '57P02', '57P03']);

type ErrorResponse = { severity?: string; code?: string };

function isConnectionLevel(message: ErrorResponse): boolean {
  // `severity` is the localized S field; the SQLSTATE also covers non-English server messages.
  if (message.severity === 'FATAL' || message.severity === 'PANIC') return true;
  const code = message.code ?? '';
  return code.startsWith('08') || CONNECTION_LEVEL_SQLSTATES.has(code);
}

function ignoreConnectionError(): void {}

class DefaultClient extends pg.Client {
  constructor(clientConfig?: pg.ClientConfig) {
    super(clientConfig);
    // Registered before pg attaches its own handler on connect, so the client is already
    // unqueryable when the running query's callback rejects.
    this.connection.on('errorMessage', (message: ErrorResponse) => {
      if (isConnectionLevel(message)) this.discardOnRelease();
    });
    this.on('error', () => {
      this.discardOnRelease();
    });
  }

  /** pg-pool removes a client that is not queryable when it is released. */
  private discardOnRelease(): void {
    (this as unknown as { _queryable: boolean })._queryable = false;
  }
}

/** Pool used when the caller supplies no poolFactory; factory pools are left untouched. */
function defaultPool(config: pg.PoolConfig): pg.Pool {
  const pool = new pg.Pool({ ...config, Client: DefaultClient });
  pool.on('error', ignoreConnectionError);
  return pool;
}

/**
 * Creates a Kysely instance bound to schema `app`, backed by its own pg pool.
 * Call `destroyDb` to close the pool.
 *
 * Platform-managed handles supply poolFactory for error handling and bounded shutdown.
 */
export function createDb(opts: CreateDbOptions): Kysely<DB> {
  const config: pg.PoolConfig = {
    types: int8AsBigInt(),
  };
  if (opts.connectionString !== undefined) {
    config.connectionString = opts.connectionString;
  }
  if (opts.max !== undefined) {
    config.max = opts.max;
  }
  if (opts.applicationName !== undefined) {
    config.application_name = opts.applicationName;
  }
  const pool = opts.poolFactory?.(config) ?? defaultPool(config);
  return new Kysely<DB>({ dialect: new PostgresDialect({ pool }) }).withSchema(APP_SCHEMA);
}

/** Closes the pool behind a Kysely instance created by `createDb`. */
export async function destroyDb(db: Kysely<DB>): Promise<void> {
  await db.destroy();
}
